package com.aicommerce.platform.delivery.application.port;
import java.math.BigDecimal; import java.time.Instant; import java.util.*; import com.aicommerce.platform.delivery.domain.*;
public record PlatformAdSetCommand(PlatformCommandIdentity identity,UUID platformAdSetUuid,UUID platformCampaignUuid,PlatformBudgetType budgetType,BigDecimal budgetAmount,String currency,Optional<Instant> scheduleStart,Optional<Instant> scheduleEnd,String accountTimezone,String optimizationGoal,String targetingProfileKey,String placementProfileKey,PlatformDesiredState desiredState){public PlatformAdSetCommand{PlatformContractSupport.req(identity);PlatformContractSupport.req(platformAdSetUuid);PlatformContractSupport.req(platformCampaignUuid);PlatformContractSupport.req(budgetType);budgetAmount=PlatformContractSupport.money(budgetAmount);scheduleStart=PlatformContractSupport.opt(scheduleStart);scheduleEnd=PlatformContractSupport.opt(scheduleEnd);if(scheduleStart.isPresent()!=scheduleEnd.isPresent()||(scheduleStart.isPresent()&&!scheduleEnd.get().isAfter(scheduleStart.get()))||!"TWD".equals(currency)||!"Asia/Taipei".equals(accountTimezone)||optimizationGoal==null||optimizationGoal.isBlank()||!"TW_BROAD_FEEDS_V1".equals(targetingProfileKey)||!"TW_BROAD_FEEDS_V1".equals(placementProfileKey)||desiredState!=PlatformDesiredState.PAUSED)throw PlatformContractSupport.invalid();}}
